namespace CSharpPracticum.Tasks.Level2;
internal enum DayOfWeek { Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday }
internal class Task21_DayOfWeek:ITask{public string Title=>"Задание 21: enum дни недели";public string Description=>"Определить выходные дни и вывести русские названия.";public string[] Requirements=>new[]{"enum DayOfWeek с семью днями.","Методы IsWeekend и GetRussianName.","Показать все 7 дней."};private static bool IsWeekend(DayOfWeek d)=>d is DayOfWeek.Saturday or DayOfWeek.Sunday;private static string GetRussianName(DayOfWeek d)=>new[]{"Понедельник","Вторник","Среда","Четверг","Пятница","Суббота","Воскресенье"}[(int)d];public void Run(){foreach(DayOfWeek d in Enum.GetValues<DayOfWeek>())Console.WriteLine($"{GetRussianName(d)}: выходной — {IsWeekend(d)}");}}
